P_prime = [
    2, 3, 4, 5, 6, 7, 8, 9, 10, 12, 14, 15, 16, 18, 20, 21, 24, 25, 27, 28, 30, 32, 35, 40, 42, 45, 48, 49
]

def is_good_set_size_4(U):
    # Condition 2a: gcd of any three distinct elements is 1
    for triplet in combinations(U, 3):
        if math.gcd(*triplet) != 1:
            return False

    # Condition 2b: For any pair (u_i, u_j), there exists u_k in U \ {u_i, u_j} such that u_k | u_i u_j
    for pair in combinations(U, 2):
        u_i, u_j = pair
        product = u_i * u_j

        # Candidates for u_k are the remaining two elements
        remaining_elements = [u for u in U if u not in pair]

        found_divisor = False
        for u_k in remaining_elements:
            if product % u_k == 0:
